-- Adds 2 new Module 6 lessons filling gaps found against DeepLearning.AI's
-- Agentic AI course: "degrees of autonomy" (agent autonomy as a spectrum, not
-- a binary) and the Reflection design pattern (one of the four classic
-- agentic design patterns -- Tool Use, Planning, and Multi-Agent were already
-- covered; Reflection was the missing fourth).
--
-- Deliberately NOT adding MCP (Model Context Protocol) or deeper production
-- topics (latency/cost optimization, component-level evals) here -- treating
-- those as more "current implementation detail" / advanced-production than
-- this foundational academy needs, rather than silently skipping them.
--
-- Anchored to lesson titles via subquery, safe regardless of current
-- numbering. Placed at the end of Module 6, after "Multi-Agent Systems".

UPDATE public.lessons SET order_index = -order_index
WHERE order_index > (SELECT order_index FROM public.lessons WHERE module_number = 6 AND title = 'Multi-Agent Systems');
UPDATE public.lessons SET order_index = -order_index + 2 WHERE order_index < 0;

WITH new_lesson AS (
  INSERT INTO public.lessons (module_number, order_index, title, slug, summary, coin_cost, is_published)
  VALUES (
    6,
    (SELECT order_index FROM public.lessons WHERE module_number = 6 AND title = 'Multi-Agent Systems') + 1,
    'Degrees of Autonomy: How Much Control to Give',
    'degrees-of-autonomy',
    'Agent autonomy is a spectrum, not a switch -- and picking the right level is a real design decision.',
    10,
    true
  )
  RETURNING id
), ins_content AS (
  INSERT INTO public.lesson_content (lesson_id, content)
  SELECT id, '{"hook":"A self-driving car at Level 0 needs a human''s foot on the pedal. At Level 5, there''s no steering wheel at all. AI agents work on the exact same spectrum.","explanation":"Agent autonomy isn''t a single on/off switch — it''s a spectrum, and choosing the right level for a given task is a real design decision, not an afterthought. A useful 4-level way to think about it: Level 1 (Suggests Only) — the agent proposes an action, a human does the actual work. Level 2 (Executes With Approval) — the agent proposes a SPECIFIC action, and a human must approve or reject it before anything runs. Level 3 (Auto-Executes Routine, Escalates Risky) — the agent runs low-risk actions on its own, but pauses for human approval on anything risky or hard to undo. Level 4 (Fully Autonomous) — the agent runs the entire task end to end with no human checkpoints at all. Higher autonomy isn''t automatically better — it trades oversight for speed, and picking too high a level for a risky task (deleting data, sending money, publishing something publicly) is a real, common way agent systems cause real damage. Most production agent systems deliberately choose LOWER autonomy than what''s technically possible, because trust has to be earned incrementally.","analogy":"It''s exactly the self-driving car autonomy levels (0 through 5) that car manufacturers actually use to describe how much a car does without a human. The same framework — how much can I trust this system to act without checking with me first — applies directly to AI agents.","fun_fact":"Many real coding agents deliberately run at different autonomy levels for different actions in the SAME session — auto-editing files freely, but always pausing for explicit approval before running a destructive command like deleting a branch or force-pushing.","try_it":"Think of a FORGE bot you could build. Pick one task it could do, and decide: should it act with zero confirmation, or should a human approve first? What makes that specific task risky or safe enough either way?","code":"def propose_action(action_description, risk_level):\n    return {\"action\": action_description, \"risk\": risk_level}\n\ndef execute_action(action):\n    print(f\"Executing: {action[''action'']}\")\n\ndef run_with_autonomy_level(action, autonomy_level):\n    if autonomy_level == \"full\":\n        execute_action(action)\n    elif autonomy_level == \"supervised\":\n        if action[\"risk\"] == \"low\":\n            execute_action(action)\n        else:\n            print(f\"NEEDS APPROVAL: {action[''action'']} (risk: {action[''risk'']})\")\n    elif autonomy_level == \"manual\":\n        print(f\"SUGGESTED ONLY: {action[''action'']}\")\n\nlow_risk = propose_action(\"Fetch today''s weather\", risk_level=\"low\")\nhigh_risk = propose_action(\"Delete all draft emails\", risk_level=\"high\")\n\nrun_with_autonomy_level(low_risk, \"supervised\")   # runs automatically\nrun_with_autonomy_level(high_risk, \"supervised\")  # pauses for approval","visual":{"caption":"How much should the agent be trusted to do on its own?","steps":[{"emoji":"1️⃣","label":"Suggests Only","caption":"Proposes an action; a human does the actual work."},{"emoji":"2️⃣","label":"Executes With Approval","caption":"Proposes a specific action, waits for a yes."},{"emoji":"3️⃣","label":"Auto-Executes, Escalates Risky","caption":"Handles routine actions alone; pauses on anything risky."},{"emoji":"4️⃣","label":"Fully Autonomous","caption":"Runs the whole task end to end, no checkpoints."}]},"practice":{"prompt":"A coding agent edits files automatically but always pauses for approval before running ''git push --force'' or deleting a branch. What autonomy level is this?","options":["Level 3 — routine actions run automatically, risky ones get escalated for approval","Level 1 — it never actually does anything itself","Level 4 — fully autonomous with zero checkpoints","This is not a real autonomy pattern"],"correct_index":0,"feedback":"Routine, low-risk edits run freely; destructive, hard-to-undo actions get escalated — the exact definition of Level 3."}}'::jsonb FROM new_lesson
  RETURNING lesson_id
)
INSERT INTO public.lesson_quiz_questions (lesson_id, order_index, question, options, correct_index, explanation)
SELECT ins_content.lesson_id, q.order_index, q.question, q.options::jsonb, q.correct_index, q.explanation
FROM ins_content, (VALUES
  (1, 'Is agent autonomy a single on/off switch?', '["No — it is a spectrum of levels, from suggesting only to fully autonomous","Yes, an agent is either fully autonomous or does nothing at all","Autonomy only applies to self-driving cars, not AI agents","Autonomy level is decided randomly each time an agent runs"]', 0, 'Real agent design treats autonomy as a deliberate spectrum, not a binary choice.'),
  (2, 'At which level does an agent propose a specific action and wait for explicit human approval before running it?', '["Level 2 — Executes With Approval","Level 1 — Suggests Only","Level 4 — Fully Autonomous","None of these levels involve approval"]', 0, 'Level 2 is defined by a specific proposed action that requires a yes before it runs.'),
  (3, 'Why do many real agent systems deliberately choose LOWER autonomy than what is technically possible?', '["Trust has to be earned incrementally, and higher autonomy trades away oversight for speed","Lower autonomy is always technically easier to build","Higher autonomy is illegal in most countries","AI agents are incapable of higher autonomy levels"]', 0, 'Choosing autonomy level is a real risk/oversight tradeoff, not just a technical capability question.'),
  (4, 'In the code example, why did the high-risk action get flagged for approval instead of running automatically?', '["Because the \"supervised\" autonomy level only auto-executes low-risk actions","Because the code has a bug","Because high-risk actions can never be executed by any agent","Because the action description was too long"]', 0, 'The supervised level checks the risk field and only auto-runs low-risk actions, escalating everything else.'),
  (5, 'What real-world risk does picking TOO HIGH an autonomy level for a risky task create?', '["The agent could take a damaging, hard-to-undo action (deleting data, sending money) with no human checkpoint","The agent would simply run slower than expected","There is no real risk to picking a high autonomy level","The agent would refuse to do anything at all"]', 0, 'This is a common, real way agent systems cause real damage — no oversight on an irreversible action.'),
  (6, 'What everyday framework is the autonomy-level idea directly borrowed from?', '["Self-driving car autonomy levels (0 through 5)","Video game difficulty settings","Musical scale notation","Programming language version numbers"]', 0, 'The same "how much can I trust this system to act without me" question is what car autonomy levels describe too.'),
  (7, 'A task is low-risk and easily reversible (like fetching public weather data). What autonomy level is usually appropriate?', '["Higher autonomy is reasonable, since mistakes cost little and are easy to undo","It must always require full manual approval no matter what","It should never be automated under any circumstances","Autonomy level has nothing to do with risk or reversibility"]', 0, 'Low-risk, reversible tasks are exactly where higher autonomy is a reasonable, low-cost choice.')
) AS q(order_index, question, options, correct_index, explanation);

WITH new_lesson AS (
  INSERT INTO public.lessons (module_number, order_index, title, slug, summary, coin_cost, is_published)
  VALUES (
    6,
    (SELECT order_index FROM public.lessons WHERE module_number = 6 AND title = 'Multi-Agent Systems') + 2,
    'Reflection: Teaching Your Agent to Self-Critique',
    'reflection-design-pattern',
    'The fourth classic agentic design pattern: generate, critique, revise -- no new tools required.',
    10,
    true
  )
  RETURNING id
), ins_content AS (
  INSERT INTO public.lesson_content (lesson_id, content)
  SELECT id, '{"hook":"The single easiest way to improve an agent''s output costs zero new tools: just ask it to check its own work.","explanation":"Reflection is one of the four classic agentic design patterns — alongside Tool Use, Planning, and Multi-Agent, which you''ve already covered. It works by having the agent generate a first attempt, then explicitly critique that attempt against clear criteria, then revise based on its own critique — often producing a noticeably better final result than a single pass ever would. This works because generating and critiquing are genuinely different tasks: producing an answer from scratch is harder than spotting a flaw in an answer that already exists, the same way it''s easier to find bugs in code someone else wrote than to write bug-free code the first time. A reflection loop can run once, or repeat several times until the critique comes back clean.","analogy":"It''s the difference between submitting your first draft of an essay versus reading it back, marking it up in red pen, and rewriting the weak parts. Same writer, same skill — a very different final result.","fun_fact":"Reflection can improve output quality without any new tools, more training, or a bigger model — it''s pure process: generate, critique, revise.","try_it":"Take something an AI generated for you (an essay, code, an email). Ask it, separately, ''critique your own answer above — what''s weak, unclear, or wrong?'' Then ask it to revise based on that critique. Compare the two versions.","code":"def generate_draft(topic):\n    return f\"Here is a summary of {topic}: [first-pass answer]\"\n\ndef critique(draft):\n    issues = []\n    if \"[\" in draft:\n        issues.append(\"Draft still contains a placeholder, not real content\")\n    return issues\n\ndef revise(draft, issues):\n    if issues:\n        return draft.replace(\"[first-pass answer]\", \"a fully written-out explanation\")\n    return draft\n\ndraft = generate_draft(\"machine learning\")\nprint(f\"Draft 1: {draft}\")\n\nissues = critique(draft)\nprint(f\"Critique found: {issues}\")\n\nfinal = revise(draft, issues)\nprint(f\"Final: {final}\")","visual":{"caption":"Generate, critique, revise — the whole pattern","steps":[{"emoji":"✏️","label":"Generate a First Attempt","caption":"Produce an initial answer, without overthinking it."},{"emoji":"🔍","label":"Critique Against Criteria","caption":"Explicitly check the attempt for flaws or gaps."},{"emoji":"🔄","label":"Revise Based on the Critique","caption":"Fix exactly what the critique found."},{"emoji":"✅","label":"Repeat or Finish","caption":"Loop again, or stop once the critique comes back clean."}]},"practice":{"prompt":"Why does asking a model to critique its own output before finalizing often improve quality?","options":["Spotting a flaw in existing work is a different, often easier task than producing flawless work in one pass","It makes the model respond faster","It has no real effect on output quality","It only works when a human writes the critique instead of the AI"],"correct_index":0,"feedback":"Generating and critiquing draw on different capabilities — the same reason a fresh pass of editing catches things the original writing missed."},"code_practice":{"instructions":"The critique function is missing a check. Add a check that flags the draft if it has fewer than 5 words.","starter":"def generate_draft(topic):\n    return f\"AI is powerful.\"\n\ndef critique(draft):\n    issues = []\n    # TODO: add a check that flags the draft if it has fewer than 5 words\n    return issues\n\ndraft = generate_draft(\"AI\")\nprint(critique(draft))","check_pattern":"len\\(.*split\\(\\).*\\)\\s*<\\s*\\d","success_message":"That''s it — now short, underdeveloped drafts get caught by the critique step before they''d ever be treated as final.","hint":"Try: if len(draft.split()) < 5: issues.append(\"Too short\")"}}'::jsonb FROM new_lesson
  RETURNING lesson_id
)
INSERT INTO public.lesson_quiz_questions (lesson_id, order_index, question, options, correct_index, explanation)
SELECT ins_content.lesson_id, q.order_index, q.question, q.options::jsonb, q.correct_index, q.explanation
FROM ins_content, (VALUES
  (1, 'What is the Reflection design pattern?', '["Having an agent generate an attempt, critique it against clear criteria, then revise based on that critique","Having two separate agents argue with each other","A pattern that only works on image-generation tasks","Randomly regenerating an answer until it happens to look different"]', 0, 'Reflection is specifically the generate -> critique -> revise loop applied to an agent''s own output.'),
  (2, 'Reflection is one of how many classic agentic design patterns?', '["Four — alongside Tool Use, Planning, and Multi-Agent","One — it is the only real agentic pattern","Ten","Reflection is not considered a real design pattern"]', 0, 'Tool Use, Planning, Multi-Agent, and Reflection are the four patterns — you have now covered all four.'),
  (3, 'Why can critiquing be an easier task than generating a flawless answer in one pass?', '["Spotting a flaw in existing work draws on different, often easier judgment than producing it correctly the first time","Critiquing and generating are exactly the same task with no real difference","Critiquing is always technically impossible for an AI to do","Generating a first attempt takes longer than any critique ever could"]', 0, 'This mirrors how it is easier to find bugs in someone else''s code than to write bug-free code from scratch.'),
  (4, 'In the code example, what did the critique step actually check for?', '["Whether the draft still contained an unfinished placeholder","Whether the draft was written in French","Whether the draft was longer than 1000 words","Nothing — the critique function always returns an empty list"]', 0, 'The critique looked for the literal "[" placeholder text left over from the first-pass draft.'),
  (5, 'Can a reflection loop run more than once on the same task?', '["Yes — it can repeat several times until the critique comes back clean","No, it can only ever run exactly one time","Reflection loops always run exactly 100 times","Reflection loops are not allowed to repeat by definition"]', 0, 'Repeating generate-critique-revise until no issues remain is a normal, valid use of the pattern.'),
  (6, 'What resource does Reflection require that Tool Use does NOT?', '["None — Reflection needs no new tools, more training, or a bigger model, just an extra generate-critique-revise pass","A completely separate, more powerful model","An internet connection","A human reviewer for every single reflection cycle"]', 0, 'Reflection is pure process — the same model, just applied twice with a critique step in between.'),
  (7, 'What does the essay-editing analogy in this lesson illustrate about Reflection?', '["A second, critical pass over your own work reliably improves it, without becoming a different writer","Editing an essay has nothing to do with AI agents","The first draft of anything is always the best version","Reflection only works for written essays, not code or other tasks"]', 0, 'Same skill, same "writer" — but reviewing and revising produces a meaningfully better result than a single pass.')
) AS q(order_index, question, options, correct_index, explanation);
